<?php
require_once __DIR__ . '/../app/bootstrap.php'; require_once __DIR__ . '/../app/controllers/AdminFeatureController.php';
Auth::requireLogin(); $controller = new AdminFeatureController(); $feedback = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST' && CSRF::verify()) $feedback = $controller->submitConcern(Auth::userId(), (string) ($_POST['subject'] ?? ''), (string) ($_POST['description'] ?? ''));
$concerns = $controller->listConcerns(Auth::userId()); $pageTitle = 'Support & Concerns'; $currentPage = 'support'; $userDisplayName = Auth::userName(); ob_start();
?><div class="row g-4"><div class="col-lg-5"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="fw-bold mb-1">Submit a concern</h2><p class="text-muted mb-4">Send a basic ticket to the EcoPick admin team.</p><?php if ($feedback): ?><div class="alert alert-<?php echo $feedback['success'] ? 'success' : 'danger'; ?>"><?php echo Validator::escape($feedback['message']); ?></div><?php endif; ?><form method="post"><?php echo CSRF::field(); ?><label class="form-label" for="subject">Subject</label><input class="form-control mb-3" id="subject" name="subject" maxlength="160" required><label class="form-label" for="description">Description</label><textarea class="form-control mb-3" id="description" name="description" rows="6" required></textarea><button class="btn btn-primary">Submit concern</button></form></div></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body p-4"><h4 class="fw-bold mb-3">My submitted concerns</h4><?php foreach ($concerns as $concern): ?><div class="border-bottom py-3"><div class="d-flex justify-content-between"><strong><?php echo Validator::escape($concern['subject']); ?></strong><span class="badge text-bg-secondary"><?php echo Validator::escape($concern['status']); ?></span></div><p class="mb-1 text-muted"><?php echo nl2br(Validator::escape($concern['description'])); ?></p><?php if (!empty($concern['admin_note'])): ?><div class="small"><strong>Admin:</strong> <?php echo Validator::escape($concern['admin_note']); ?></div><?php endif; ?></div><?php endforeach; ?><?php if (!$concerns): ?><p class="text-muted mb-0">No concerns submitted.</p><?php endif; ?></div></div></div></div><?php $content = ob_get_clean(); require_once __DIR__ . '/../app/views/user_dashboard_shell.php';